class Room {
  final int x;
  final int y;
  final int width;
  final int height;
  Room(this.x, this.y, this.width, this.height);
  Point get center => Point(x + width ~/ 2, y + height ~/ 2);
}
class Region {
  final int x;
  final int y;
  final int width;
  final int height;
  Region? first;
  Region? second;
  var leaf = -1;
  Region(this.x, this.y, this.width, this.height);
}

class Level {
  final int depth;
  final int width;
  final int height;
  final List<List<String>> terrain;
  final List<List<String>> memory;
  final rooms = <Room>[];
  late Point arrival;
  late Point target;
  late int arrivalRoom;
  final monsters = <Monster>[];
  final items = <Item>[];
  var monstersCreated = 0, itemsPlaced = 0, kills = 0, picked = 0;
  Level(this.depth, this.width, this.height)
      : terrain = List.generate(height, (_) => List.filled(width, ' ')), memory = List.generate(height, (_) => List.filled(width, ' '));
  Monster? monsterAt(int x, int y) {
    for (final monster in monsters) {
      if (monster.position == Point(x, y)) {
        return monster;
      }
    }
    return null;
  }
  Item? itemAt(int x, int y) {
    for (final item in items) {
      if (item.position == Point(x, y)) {
        return item;
      }
    }
    return null;
  }
  Point drawInteriorCell(Minstd rng, int index) {
    final room = rooms[index];
    final x = room.x + 1 + rng.rnd(room.width - 2);
    final y = room.y + 1 + rng.rnd(room.height - 2);
    return Point(x, y);
  }
  (int, Point) drawRoomCell(Minstd rng) {
    final index = rng.rnd(rooms.length);
    return (index, drawInteriorCell(rng, index));
  }
}

class LevelGenerator {
  final Minstd rng;
  final int minSize;
  final int maxSplit;
  final int roomMin;
  final int roomMax;
  LevelGenerator(this.rng, this.minSize, this.maxSplit, this.roomMin, this.roomMax);
  Level generate(int depth, int width, int height) {
    final level = Level(depth, width, height);
    final root = Region(0, 0, width, height);
    final leaves = <Region>[];
    split(root, 0, leaves);
    for (final leaf in leaves) {
      level.rooms.add(makeRoom(level, leaf));
    }
    connect(level, root);
    final (room, point) = level.drawRoomCell(rng);
    level.terrain[point.y][point.x] = '<';
    level.arrival = point;
    level.arrivalRoom = room;
    var other = rng.rnd(level.rooms.length - 1);
    if (other >= room) {
      other++;
    }
    level.target = level.drawInteriorCell(rng, other);
    return level;
  }

  void split(Region region, int depth, List<Region> leaves) {
    final cv = region.width >= 2 * minSize, ch = region.height >= 2 * minSize;
    if (depth == maxSplit || (!cv && !ch)) {
      region.leaf = leaves.length;
      leaves.add(region);
      return;
    }
    var vertical = cv;
    if (cv && ch) {
      if (4 * region.width >= 5 * region.height) {
        vertical = true;
      } else if (4 * region.height >= 5 * region.width) {
        vertical = false;
      } else {
        vertical = rng.rnd(2) == 0;
      }
    }
    if (vertical) {
      final cut = minSize + rng.rnd(region.width - 2 * minSize + 1);
      region.first = Region(region.x, region.y, cut, region.height);
      region.second = Region(region.x + cut, region.y, region.width - cut, region.height);
    } else {
      final cut = minSize + rng.rnd(region.height - 2 * minSize + 1);
      region.first = Region(region.x, region.y, region.width, cut);
      region.second = Region(region.x, region.y + cut, region.width, region.height - cut);
    }
    split(region.first!, depth + 1, leaves);
    split(region.second!, depth + 1, leaves);
  }

  Room makeRoom(Level level, Region region) {
    final width = roomMin + rng.rnd(math.min(roomMax, region.width - 1) - roomMin + 1);
    final height = roomMin + rng.rnd(math.min(roomMax, region.height - 1) - roomMin + 1);
    final x = region.x + rng.rnd(region.width - width);
    final y = region.y + rng.rnd(region.height - height);
    for (var row = y; row < y + height; row++) {
      for (var column = x; column < x + width; column++) {
        level.terrain[row][column] = row == y || row == y + height - 1 ? '-' : column == x || column == x + width - 1 ? '|' : '.';
      }
    }
    return Room(x, y, width, height);
  }

  List<int> connect(Level level, Region region) {
    if (region.leaf >= 0) {
      return [region.leaf];
    }
    final first = connect(level, region.first!);
    final second = connect(level, region.second!);
    var aBest = -1, bBest = -1, bestDistance = 0;
    for (final a in first) {
      for (final b in second) {
        final pa = level.rooms[a].center, pb = level.rooms[b].center;
        final distance = (pa.x - pb.x).abs() + (pa.y - pb.y).abs();
        if (aBest < 0 || distance < bestDistance) {
          aBest = a;
          bBest = b;
          bestDistance = distance;
        }
      }
    }
    dig(level, level.rooms[aBest].center, level.rooms[bBest].center, rng.rnd(2) == 0);
    return [...first, ...second];
  }

  void dig(Level level, Point start, Point end, bool horizontal) {
    void digCell(int x, int y) {
      if (level.terrain[y][x] == ' ') {
        level.terrain[y][x] = '#';
      } else if (level.terrain[y][x] == '-' || level.terrain[y][x] == '|') {
        level.terrain[y][x] = '+';
      }
    }
    void horizontalLeg(int y, int x0, int x1) {
      final step = x1 >= x0 ? 1 : -1;
      for (var x = x0;; x += step) {
        digCell(x, y);
        if (x == x1) {
          break;
        }
      }
    }
    void verticalLeg(int x, int y0, int y1) {
      final step = y1 >= y0 ? 1 : -1;
      for (var y = y0;; y += step) {
        digCell(x, y);
        if (y == y1) {
          break;
        }
      }
    }
    if (horizontal) {
      horizontalLeg(start.y, start.x, end.x);
      verticalLeg(end.x, start.y, end.y);
    } else {
      verticalLeg(start.x, start.y, end.y);
      horizontalLeg(end.y, start.x, end.x);
    }
  }
}

import 'combat.dart';

class Point {
  final int x;
  final int y;
  const Point(this.x, this.y);
  @override
  bool operator ==(Object other) => other is Point && x == other.x && y == other.y;
  @override
  int get hashCode => Object.hash(x, y);
}

class MonsterType {
  final int index;
  final String name;
  final String symbol;
  final int minDepth;
  final int maxDepth;
  final int weight;
  final Dice hp;
  final int toHit;
  final int defense;
  final Dice damage;
  final int speed;
  final int xp;
  final bool erratic;
  final bool stationary;
  final bool regenerates;
  final bool poisonous;
  MonsterType(List<String> tokens, this.index)
      : name = tokens[0], symbol = tokens[1], minDepth = int.parse(tokens[2]), maxDepth = int.parse(tokens[3]),
        weight = int.parse(tokens[4]), hp = parseDice(tokens[5]), toHit = int.parse(tokens[6]), defense = int.parse(tokens[7]),
        damage = parseDice(tokens[8]), speed = int.parse(tokens[9]), xp = int.parse(tokens[10]),
        erratic = tokens[11].contains('E'), stationary = tokens[11].contains('S'), regenerates = tokens[11].contains('R'), poisonous = tokens[11].contains('P');
}

class ItemType {
  final String category;
  final String name;
  final int minDepth;
  final int maxDepth;
  final int weight;
  Dice? dice;
  var toHit = 0, armor = 0, poisonTurns = 0, nutrition = 0;
  var effect = '';
  ItemType(this.category, this.name, [this.minDepth = 0, this.maxDepth = 0, this.weight = 0]);
}

ItemType parseItemType(List<String> tokens) {
  final kind = ItemType(tokens[0], tokens[1], int.parse(tokens[2]), int.parse(tokens[3]), int.parse(tokens[4]));
  final args = tokens.sublist(5);
  switch (kind.category) {
    case 'weapon':
      kind.dice = parseDice(args[0]);
      kind.toHit = int.parse(args[1]);
    case 'armor':
      kind.armor = int.parse(args[0]);
    case 'potion':
      kind.effect = args[0];
      if (kind.effect == 'heal') {
        kind.dice = parseDice(args[1]);
      } else if (kind.effect == 'poison') {
        kind.poisonTurns = int.parse(args[1]);
      }
    case 'scroll':
      kind.effect = args[0];
    case 'food':
      kind.nutrition = int.parse(args[0]);
    case 'gold':
      kind.dice = parseDice(args[0]);
  }
  return kind;
}

class Monster {
  final int id;
  final MonsterType kind;
  Point position;
  int hp;
  final int maxHP;
  bool asleep;
  var energy = 0;
  var wasVisible = false;
  Monster(this.id, this.kind, this.position, this.hp, this.asleep) : maxHP = hp;
}

class Item {
  final ItemType kind;
  final Point position;
  final int amount;
  var bonus = 0;
  Item(this.kind, this.position, [this.amount = 0]);
  String get symbol => switch (kind.category) {'weapon' => ')', 'armor' => '[', 'potion' => '!', 'scroll' => '?', 'food' => '%', 'gold' => r'$', 'amulet' => '"', _ => throw StateError('Unknown item class')};
  String get displayName {
    final name = kind.name.replaceAll('_', ' ');
    if (kind.category == 'weapon' || kind.category == 'armor') {
      return '+$bonus $name';
    }
    return kind.category == 'gold' ? '$amount gold' : name;
  }
  String get referenceName => kind.category == 'gold' ? displayName : 'the $displayName';
}

import 'dart:math' as math;
import 'dungeon_gen.dart';
import 'entities.dart';

const directionNames = ['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW'];
const directions = [Point(0, -1), Point(1, -1), Point(1, 0), Point(1, 1), Point(0, 1), Point(-1, 1), Point(-1, 0), Point(-1, -1)];
bool passable(Level level, int x, int y) => ['.', '#', '+', '<', '>'].contains(level.terrain[y][x]);
bool canMove(Level level, int x, int y, int dx, int dy) => passable(level, x + dx, y + dy) &&
    (dx == 0 || dy == 0 || (level.terrain[y][x] != '+' && level.terrain[y + dy][x + dx] != '+'));

List<Point> line(int x0, int y0, int x1, int y1) {
  final dx = (x1 - x0).abs(), dy = (y1 - y0).abs();
  final sx = x1 > x0 ? 1 : -1, sy = y1 > y0 ? 1 : -1;
  var error = dx - dy, x = x0, y = y0;
  final cells = <Point>[];
  while (x != x1 || y != y1) {
    final e2 = 2 * error;
    if (e2 > -dy) {
      error -= dy;
      x += sx;
    }
    if (e2 < dx) {
      error += dx;
      y += sy;
    }
    cells.add(Point(x, y));
  }
  return cells;
}

List<List<bool>> fieldOfView(Level level, int px, int py, int radius) {
  final visible = List.generate(level.height, (_) => List.filled(level.width, false));
  for (var y = math.max(0, py - radius); y < math.min(level.height, py + radius + 1); y++) {
    for (var x = math.max(0, px - radius); x < math.min(level.width, px + radius + 1); x++) {
      if ((x - px) * (x - px) + (y - py) * (y - py) > radius * radius) {
        continue;
      }
      final cells = line(px, py, x, y);
      visible[y][x] = cells.take(math.max(0, cells.length - 1)).every((point) => passable(level, point.x, point.y));
    }
  }
  return visible;
}

List<List<int>> distances(Level level, int px, int py) {
  final result = List.generate(level.height, (_) => List.filled(level.width, -1));
  result[py][px] = 0;
  final queue = [Point(px, py)];
  for (var head = 0; head < queue.length; head++) {
    final point = queue[head];
    for (final step in directions) {
      final nx = point.x + step.x, ny = point.y + step.y;
      if (canMove(level, point.x, point.y, step.x, step.y) && result[ny][nx] < 0) {
        result[ny][nx] = result[point.y][point.x] + 1;
        queue.add(Point(nx, ny));
      }
    }
  }
  return result;
}

